#!/usr/bin/env python3
"""
Fetch USGS streamflow data and identify flood events.
A flood day is defined by high streamflow relative to the station's typical flows.
"""

import requests
import csv
from datetime import datetime, timedelta
from collections import defaultdict

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    station_ids = [line.strip() for line in f if line.strip()]

print(f"Found {len(station_ids)} stations")

# Date range for analysis: April 1-7, 2025
start_date = datetime(2025, 4, 1)
end_date = datetime(2025, 4, 7)

# USGS API endpoint
USGS_API = "https://waterservices.usgs.gov/nwis/dv"

# Store all station data
station_data = {}

print("Fetching April 1-7, 2025 data...")
for idx, station_id in enumerate(station_ids, 1):
    print(f"[{idx}/{len(station_ids)}] Station {station_id}...", end=" ", flush=True)

    try:
        # Fetch daily mean discharge data for the flood period
        params = {
            'sites': station_id,
            'startDT': start_date.strftime('%Y-%m-%d'),
            'endDT': end_date.strftime('%Y-%m-%d'),
            'parameterCd': '00060',  # Discharge code
            'siteStatus': 'all',
            'format': 'json'
        }

        response = requests.get(USGS_API, params=params, timeout=10)
        response.raise_for_status()

        data = response.json()

        # Parse the response
        if 'value' not in data or 'timeSeries' not in data['value']:
            print("No data")
            continue

        daily_flows = []

        for time_series in data['value']['timeSeries']:
            if 'values' not in time_series:
                continue

            for value_array in time_series['values']:
                if 'value' not in value_array:
                    continue

                for value in value_array['value']:
                    try:
                        discharge = float(value.get('value'))
                        date_str = value.get('dateTime', '')

                        if discharge >= 0:  # Valid measurement
                            daily_flows.append({
                                'date': date_str,
                                'discharge': discharge
                            })
                    except (ValueError, TypeError):
                        continue

        if daily_flows:
            station_data[station_id] = daily_flows
            print(f"OK ({len(daily_flows)} days)")
        else:
            print("No valid data")

    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Error: {e}")

print(f"\nSuccessfully retrieved data for {len(station_data)} stations")

# Now fetch historical data (past 10 years) to establish baseline for each station
print("\nFetching historical baseline data (2015-2024)...")

station_baselines = {}

for idx, station_id in enumerate(station_ids, 1):
    if idx % 10 == 0:
        print(f"[{idx}/{len(station_ids)}] Processing baselines...", end=" ", flush=True)

    try:
        # Fetch historical daily mean discharge data
        params = {
            'sites': station_id,
            'startDT': '2015-01-01',
            'endDT': '2024-12-31',
            'parameterCd': '00060',  # Discharge code
            'siteStatus': 'all',
            'format': 'json'
        }

        response = requests.get(USGS_API, params=params, timeout=10)
        response.raise_for_status()

        data = response.json()

        # Parse the response
        if 'value' not in data or 'timeSeries' not in data['value']:
            continue

        historical_flows = []

        for time_series in data['value']['timeSeries']:
            if 'values' not in time_series:
                continue

            for value_array in time_series['values']:
                if 'value' not in value_array:
                    continue

                for value in value_array['value']:
                    try:
                        discharge = float(value.get('value'))
                        date_str = value.get('dateTime', '')

                        if discharge >= 0:  # Valid measurement
                            historical_flows.append(discharge)
                    except (ValueError, TypeError):
                        continue

        if historical_flows:
            station_baselines[station_id] = historical_flows

    except requests.exceptions.RequestException:
        continue
    except Exception:
        continue

if len(station_baselines) > 0:
    print(f"OK ({len(station_baselines)} stations)")

# Analyze flood conditions
print("\nAnalyzing flood conditions...")

final_results = {}

for station_id, daily_data in station_data.items():
    if station_id not in station_baselines or not station_baselines[station_id]:
        # Use a default threshold if no baseline available
        discharges = [d['discharge'] for d in daily_data]
        if not discharges:
            continue

        # For stations without baseline, consider flows > median of current data as floods
        median_flow = sorted(discharges)[len(discharges) // 2]
        flood_threshold = median_flow * 2.0  # 2x median as threshold
    else:
        historical = station_baselines[station_id]
        # Use 90th percentile of historical data as flood threshold
        sorted_hist = sorted(historical)
        percentile_90_idx = int(len(sorted_hist) * 0.90)
        flood_threshold = sorted_hist[percentile_90_idx]

    # Count days exceeding flood threshold
    discharges = [d['discharge'] for d in daily_data]
    flood_days = sum(1 for d in discharges if d > flood_threshold)

    if flood_days > 0:
        final_results[station_id] = flood_days

# Write CSV output
print(f"Writing results to /root/output/flood_results.csv...")
with open('/root/output/flood_results.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])

    for station_id in sorted(final_results.keys()):
        writer.writerow([station_id, final_results[station_id]])

print(f"Found {len(final_results)} stations with flooding")
print("Results saved to /root/output/flood_results.csv")

# Show sample results
if final_results:
    print("\nSample results (first 10):")
    for station_id in sorted(final_results.keys())[:10]:
        print(f"  {station_id}: {final_results[station_id]} flood days")

